// Mock interview scenario: Reverse words in a sentence
// Interviewer: "Given 'hello world from java', return 'java from world hello'"
// Practice talking through this solution out loud

public String reverseWords(String sentence) {
    if (sentence == null || sentence.isEmpty()) {
        return sentence; // Edge case: handle null/empty
    }

    String[] words = sentence.trim().split("\\s+"); // Split on whitespace
    var reversed = new StringBuilder();

    // Build result from end to start
    for (int i = words.length - 1; i >= 0; i--) {
        reversed.append(words[i]);
        if (i > 0) {
            reversed.append(" "); // Add space between words
        }
    }

    return reversed.toString();
}

// In mock interview, you'd say out loud:
// "First I'll check edge cases, then split the sentence into words,
// then iterate backward to build the reversed string."

// Simulated whiteboard coding: Find first duplicate in array
// No autocomplete, no syntax highlighting, no compiler feedback
// Write this in a Google Doc during practice

public int findFirstDuplicate(int[] numbers) {
    Set<Integer> seen = new HashSet<>();

    for (int num : numbers) {
        if (seen.contains(num)) {
            return num; // Found first duplicate
        }
        seen.add(num);
    }

    return -1; // No duplicate found
}

// Without IDE, you must remember:
// - HashSet constructor (not HashSet<Integer>())
// - contains() method name (not has() or includes())
// - Enhanced for-loop syntax
// - Return type must match method signature

// Common mistakes without autocomplete:
// - Writing seen.has(num) instead of seen.contains(num)
// - Forgetting to initialize HashSet with new HashSet<>()
// - Using ArrayList instead of Set for this problem

// Pattern: Two pointers moving inward
// Problem: Remove duplicates from sorted array in-place
// This pattern appears in 20+ LeetCode problems

public int removeDuplicates(int[] nums) {
    if (nums.length == 0) return 0;

    int writePointer = 1; // Position to write next unique element

    for (int readPointer = 1; readPointer < nums.length; readPointer++) {
        // When we find a new unique element
        if (nums[readPointer] != nums[readPointer - 1]) {
            nums[writePointer] = nums[readPointer]; // Copy it forward
            writePointer++;
        }
    }

    return writePointer; // New length with unique elements
}

// Why this pattern matters:
// - No extra space used (in-place modification)
// - Two pointers technique appears in merge sorted arrays, container with most water
// - Tests understanding of array traversal without helper structures
// - Common in backend: processing sorted logs, deduplicating user lists
